package de.fitnesscoach.agent;
import static org.junit.Assert.*;import java.time.*;import org.json.JSONObject;import org.junit.Test;import de.fitnesscoach.data.entity.*;
public class AgentToolExecutorTest{@Test public void unknownToolFailsClosed(){JSONObject r=new AgentToolExecutor(new AgentTestRepository()).execute("read_entire_room_database",new JSONObject());assertFalse(r.getBoolean("success"));assertEquals("REJECTED",r.getString("code"));}@Test public void syntacticallyValidRescheduleCanBeRejectedLocally(){AgentTestRepository repo=new AgentTestRepository();LocalDate monday=LocalDate.of(2026,8,24);PlannedWorkoutEntity w=new PlannedWorkoutEntity();w.id=1;w.date=monday;w.workoutType=DomainEnums.WorkoutType.EASY;w.status=DomainEnums.WorkoutStatus.PLANNED;w.version=1;repo.planned.add(w);TrainingAvailabilityEntity unavailable=new TrainingAvailabilityEntity();unavailable.dayOfWeek=2;unavailable.available=false;repo.availability.add(unavailable);JSONObject args=new JSONObject().put("workoutId",1).put("date",monday.plusDays(1).toString());JSONObject r=new AgentToolExecutor(repo).execute("reschedule_workout",args);assertFalse(r.getBoolean("success"));assertEquals(monday,w.date);}@Test public void successfulModifyCreatesAuditRecord(){AgentTestRepository repo=new AgentTestRepository();LocalDate d=LocalDate.of(2026,8,24);TrainingAvailabilityEntity a=new TrainingAvailabilityEntity();a.dayOfWeek=d.getDayOfWeek().getValue();a.available=true;a.maxDurationMinutes=60;repo.availability.add(a);PlannedWorkoutEntity w=new PlannedWorkoutEntity();w.id=2;w.date=d;w.workoutType=DomainEnums.WorkoutType.EASY;w.status=DomainEnums.WorkoutStatus.PLANNED;w.version=1;repo.planned.add(w);JSONObject r=new AgentToolExecutor(repo).execute("modify_workout",new JSONObject().put("workoutId",2).put("durationMinutes",45));assertTrue(r.getBoolean("success"));assertEquals(Integer.valueOf(45),w.plannedDurationMinutes);assertEquals(DomainEnums.WorkoutStatus.ADAPTED,w.status);assertEquals(1,repo.decisions.size());}@Test public void adjacentIntenseRescheduleIsRejected(){AgentTestRepository repo=new AgentTestRepository();LocalDate d=LocalDate.of(2026,8,24);for(int dow:new int[]{1,2}){TrainingAvailabilityEntity a=new TrainingAvailabilityEntity();a.dayOfWeek=dow;a.available=true;a.maxDurationMinutes=90;repo.availability.add(a);}PlannedWorkoutEntity first=new PlannedWorkoutEntity();first.id=1;first.date=d;first.workoutType=DomainEnums.WorkoutType.INTERVAL;first.status=DomainEnums.WorkoutStatus.PLANNED;repo.planned.add(first);PlannedWorkoutEntity second=new PlannedWorkoutEntity();second.id=2;second.date=d.plusDays(3);second.workoutType=DomainEnums.WorkoutType.LONG;second.status=DomainEnums.WorkoutStatus.PLANNED;repo.planned.add(second);JSONObject r=new AgentToolExecutor(repo).execute("reschedule_workout",new JSONObject().put("workoutId",2).put("date",d.plusDays(1).toString()));assertFalse(r.getBoolean("success"));assertEquals(d.plusDays(3),second.date);}}
